SchoolSubject _makeEnglishSubject(String pfx) {
  final isSec = pfx.startsWith('s');
  final isMiddle = pfx.startsWith('m');
  final List<SchoolChapter> chs;
  if (isSec) {
    chs = [
      SchoolChapter(
        id: '${pfx}_en_ch1',
        name: 'Advanced Grammar',
        questions: [
          SchoolQuestion(
            id: '${pfx}_en_1_1',
            question: 'Which sentence uses the present perfect correctly?',
            options: [
              'I have visited Paris twice.',
              'I visited Paris since 2010.',
              'I have visit Paris.',
              'I am visited Paris.',
            ],
            correctAnswer: 'I have visited Paris twice.',
            funFact: 'Present perfect = have/has + past participle.',
          ),
          SchoolQuestion(
            id: '${pfx}_en_1_2',
            question: 'What is a conditional sentence type 2?',
