SchoolSubject _makeSocialSubject(String pfx) {
  final isSec = pfx.startsWith('s');
  final isMiddle = pfx.startsWith('m');
  final List<SchoolChapter> chs;
  if (isSec) {
    chs = [
      SchoolChapter(
        id: '${pfx}_soc_ch1',
        name: 'الجغرافيا البشرية والطبيعية',
        questions: [
          SchoolQuestion(
            id: '${pfx}_soc_1_1',
            question: 'ما الجغرافيا البشرية؟',
