              'دراسة العلاقة بين الإنسان وبيئته',
              'دراسة الكواكب',
              'علم الأحياء',
              'دراسة المناخ فقط',
            ],
            correctAnswer: 'دراسة العلاقة بين الإنسان وبيئته',
            funFact: 'تشمل الجغرافيا البشرية السكان والاقتصاد والثقافة.',
          ),
          SchoolQuestion(
            id: '${pfx}_soc_1_2',
            question: 'ما التوزيع السكاني؟',
            options: [
              'كيفية انتشار السكان على مساحة معينة',
              'عدد المدن',
              'مساحة الدولة',
              'معدل المواليد',
            ],
            correctAnswer: 'كيفية انتشار السكان على مساحة معينة',
            funFact: 'يتأثر التوزيع السكاني بعوامل طبيعية وبشرية.',
          ),
          SchoolQuestion(
            id: '${pfx}_soc_1_3',
            question: 'ما الهجرة الداخلية؟',
            options: [
              'انتقال السكان داخل الدولة الواحدة',
              'السفر للخارج',
              'الهجرة الدولية',
              'الهجرة الموسمية للخارج',
